-- UPDATE public.modules SET course_id = 'dsa', title = 'Core Data Structures', description = 'Fundamental data structures for efficient data organization' WHERE id = 'c9a18717-ccff-4f5d-98a8-6e6c3e2d5936' AND description IS NOT DISTINCT FROM 'Choose arrays, strings, stacks, queues, and linked structures by the operations a problem needs.';
-- UPDATE public.lessons SET module_id = '9a80cb72-efc7-4504-8454-c8dee3dd3193', title = 'Dynamic Programming and Greedy Algorithms', content = 'Breaking problems into overlapping subproblems and making locally optimal choices.' WHERE id = '57e5f4eb-45f4-4bb0-8484-ab60ea5306e9' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Distinguish a locally greedy choice from a dynamic-programming solution, then use that reasoning in a small algorithm toolkit project.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A delivery planner must choose a set of packages under a weight limit. Taking the heaviest valuable package first can block a better overall combination.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Does the best immediate choice guarantee the best total? A counterexample can invalidate a greedy rule.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Dynamic programming defines overlapping subproblems and stores answers; greedy methods make a locally best choice and need a proof that this choice remains globally optimal.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For coin change with denominations 1, 3, and 4, greedily making 6 gives 4+1+1 (three coins), while 3+3 uses two. The example shows a greedy failure; a DP table can compare totals systematically.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>For the toolkit project, combine a map or set with one search/sort operation to solve a volunteer scheduling or duplicate-detection problem. Define input/output, implement it, test empty/duplicate/boundary cases, and annotate expected growth. Present the problem, structure choice, one counterexample or test, limitation, and next improvement.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A successful algorithm needs a reason it works, not only a few examples where it appears to. The course stores lesson progress, but does not persist project submissions.</p></section>';
-- UPDATE public.lessons SET module_id = '9a80cb72-efc7-4504-8454-c8dee3dd3193', title = 'Graph Algorithms', content = 'Breadth-first search (BFS), depth-first search (DFS), Dijkstra''s algorithm, and A* search.' WHERE id = 'c28867ca-5506-414f-89ce-0f965ff706ee' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Trace breadth-first and depth-first traversal and select shortest-path methods based on edge weights.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A route planner needs a path between stations. Some routes are equal-length; others have different travel times.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Does “fewest edges” mean “shortest travel time”? The algorithm depends on what an edge and its weight represent.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>BFS finds paths with the fewest edges in an unweighted graph. DFS explores deeply and helps with reachability and structure. Dijkstra’s algorithm handles nonnegative edge weights; negative weights need different methods.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For an unweighted map, BFS explores all stations one transfer away before two transfers away. For travel minutes, use weights and do not substitute ordinary BFS.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Choose BFS, DFS, or Dijkstra for: fewest links, exploring a dependency tree, and least total time with nonnegative costs. State each graph assumption.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A graph algorithm’s correctness depends on the model and its preconditions.</p></section>';
-- UPDATE public.lessons SET module_id = 'ad569dec-e1cc-4395-ae09-f9a4150eb399', title = 'Segment Trees and Binary Indexed Trees', content = 'Data structures for storing information about intervals or segments and answering range queries.' WHERE id = '35223328-5300-4957-b6f8-5b7dbd6783de' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Recognize range-query workloads and explain how a tree can trade extra memory for faster repeated updates and queries.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A dashboard receives daily totals and repeatedly asks for the sum over a selected week, even as individual days are corrected.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Would recomputing every selected range be expensive when queries repeat? Precomputed summaries can combine smaller intervals.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A segment tree stores aggregates for intervals and supports point updates and range queries in logarithmic time with linear-scale storage. A Fenwick (binary indexed) tree is a compact option for prefix sums and point updates.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For daily counts, a query over days 4–7 can combine stored subranges rather than add every day individually. The aggregate must support the chosen combination operation.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Given millions of values, frequent point updates, and range-sum queries, explain why a Fenwick tree may fit. What would make a simple prefix array preferable?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>These structures solve a specific repeated-query tradeoff. Use them only when simpler approaches no longer meet the need.</p></section>';
-- UPDATE public.lessons SET module_id = 'ad569dec-e1cc-4395-ae09-f9a4150eb399', title = 'Disjoint Set Union (Union-Find)', content = 'Data structure that tracks a set of elements partitioned into disjoint subsets.' WHERE id = '3459221d-fd47-4b1a-9d26-e2f58546d0c0' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Use disjoint-set union to track which items belong to the same connected group as links are added.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A network technician is connecting devices and wants to know whether two devices are already in the same connected component.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Can every query recompute all connectivity from scratch? A disjoint-set structure remembers component representatives.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>`find(x)` returns a representative for x’s set; `union(a,b)` merges two sets. Path compression and union by rank/size make operations nearly constant amortized time in common analyses.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>If `find(A)=R1` and `find(B)=R2`, union merges their groups. A later find for any member should lead to the same representative.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Track groups `{A,B}`, `{C}`, `{D,E}` after `union(B,C)` then `union(A,E)`. Which pairs are connected now?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Union-Find is suited to merging connectivity groups; it does not efficiently split a group after a link is removed.</p></section>';
-- UPDATE public.lessons SET module_id = 'ad569dec-e1cc-4395-ae09-f9a4150eb399', title = 'Tries and String Processing', content = 'Tree-like structures optimized for storing and searching strings with common prefixes.' WHERE id = '1eacb909-6609-48c9-a783-2151fc45ed9e' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain how a trie shares prefixes and when that can help prefix search.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A search box suggests place names after each typed character. Rechecking every full name from scratch wastes repeated prefix work.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What do “San” and “Santa” share? A trie represents common prefixes as shared paths.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A trie stores keys one symbol at a time along edges. Prefix lookup follows the typed path, then explores descendants for matches. Memory use can be high, especially with sparse alphabets.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For “map,” “man,” and “mat,” the path `m → a` is shared, then the final letters branch. Define case, Unicode normalization, and maximum suggestion count for a real search.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Draw a trie for “cat,” “car,” and “dog.” Circle the prefix path for “ca” and identify a memory tradeoff.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A specialized structure helps when its operation matches the product need; prefix search is the trie’s strength.</p></section>';
-- UPDATE public.lessons SET module_id = 'ad569dec-e1cc-4395-ae09-f9a4150eb399', title = 'Heaps and Priority Queues', content = 'Complete binary trees where parent nodes follow heap property relative to children.' WHERE id = '3f77c0d0-f5dc-4159-a114-bdfcefb45051' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Use a heap-backed priority queue when the next item should be chosen by priority rather than arrival order.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A clinic receptionist needs to bring the most urgent waiting case to the top while preserving a clear tie-breaking rule.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>A normal queue serves first-in-first-out, but urgency changes the selection rule. A priority queue makes that rule explicit.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A binary heap is a nearly complete tree with a parent-child priority invariant. It supports retrieving the highest or lowest priority efficiently; it does not keep every item fully sorted.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Insert tasks with priorities 2, 5, and 3 into a max-priority queue. The next task has priority 5; ties need a documented policy such as earlier arrival first.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Choose a heap or regular queue for an email outbox and an emergency alert dispatcher. What can go wrong if equal priorities have no stable ordering?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Choose a priority queue when selection by rank is central; do not use a heap as if it were a sorted array.</p></section>';
-- UPDATE public.lessons SET module_id = '9a80cb72-efc7-4504-8454-c8dee3dd3193', title = 'Asymptotic Notation', content = 'Mathematical tools to describe algorithm efficiency and scalability as input size grows.' WHERE id = 'b5aa0b3b-7189-4449-a8f3-c6dbe23ecd39' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Use Big O as a high-level description of how work grows with input size.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A report that scans every pair of customer records works for 100 rows but slows sharply when records reach one million.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>How does doubling input change the work? Growth helps compare approaches before timing them on one machine.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>O(n) grows roughly with input length; O(n²) can grow about four times when input doubles; O(log n) grows slowly. Big O omits constants and does not predict exact runtime.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A nested loop over all pairs has quadratic work. A single pass to count values in a map is typically linear expected work, plus map operations.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Estimate the growth of one loop over n items and two nested loops over n items. Which would you measure first for n=10,000?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Complexity is a comparison tool. State assumptions and use measurements to check real workloads.</p></section>';
-- UPDATE public.lessons SET module_id = '9a80cb72-efc7-4504-8454-c8dee3dd3193', title = 'Sorting Algorithms', content = 'Bubble sort, selection sort, insertion sort, merge sort, quicksort, heap sort, and counting sort.' WHERE id = 'af8f9e8d-3406-4a69-b801-18567623a0a5' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Describe a sorting algorithm’s work and choose a practical approach for a given input size and constraint.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A store wants products ordered by price, while keeping products with equal prices in their original display order.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Does equal-key order matter? Stability and memory can matter as much as the headline runtime.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Simple insertion sort can be effective for small or nearly sorted lists but has quadratic worst-case comparisons. Efficient general sorts often use O(n log n) comparisons; exact behavior depends on implementation and input.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For `[3, 1, 2]`, insertion sort grows a sorted prefix: `[1, 3, 2]`, then `[1, 2, 3]`. A stable sort preserves the relative order of equal prices.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Sort five named tasks by priority and retain arrival order for ties. State the property your chosen sort must preserve.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Measure the complete behavior you need: correctness, stability, memory, and performance.</p></section>';
-- UPDATE public.lessons SET module_id = '9a80cb72-efc7-4504-8454-c8dee3dd3193', title = 'Searching Algorithms', content = 'Linear search, binary search, and search algorithms for specialized data structures.' WHERE id = 'a37b9636-fbd0-4646-b7b2-5868b4cb39d8' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Compare linear and binary search and state the precondition for binary search.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A librarian checks a shelf of unsorted returns, then later searches a catalog sorted by title.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Can the librarian safely skip half the sorted catalog? Only if the order is correct and stable for the chosen comparison.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Linear search checks items in sequence and works without sorting. Binary search repeatedly halves a sorted range, taking logarithmic comparisons; on unsorted data, that elimination rule is invalid.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>In 16 sorted values, binary search needs at most about 5 comparisons because 16→8→4→2→1. Linear search might inspect all 16.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Choose a method for one lookup in an unsorted list and for thousands of lookups in a sorted list. Include sorting cost and update frequency in your reasoning.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Algorithm choice includes preconditions and the cost of preparing data, not only the search loop.</p></section>';
-- UPDATE public.lessons SET module_id = 'ad569dec-e1cc-4395-ae09-f9a4150eb399', title = 'Graphs and Graph Representations', content = 'Collections of nodes (vertices) connected by edges, represented as adjacency matrices or lists.' WHERE id = '37d55a4f-f6f7-4791-9518-d90cdc927503' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Model entities and relationships as vertices and edges, including direction and weight when needed.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A transit planner must represent stations connected by routes, where some routes take longer or operate in one direction.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Are connections symmetric? A list of stations alone cannot express all route relationships.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A graph has vertices and edges. Edges may be directed or undirected and may carry weights. An adjacency list stores each vertex’s neighbors efficiently for many sparse graphs.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Represent a one-way bus route A→B with an edge and travel time as its weight. Do not assume B→A exists unless the data says so.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Model three people connected by “follows” relationships. Mark directed edges and explain what a two-way friendship would require.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Choose graph details from the real relationship. Direction and weight change which algorithms are appropriate.</p></section>';
-- UPDATE public.lessons SET module_id = 'c9a18717-ccff-4f5d-98a8-6e6c3e2d5936', title = 'Trees and Binary Trees', content = 'Node-based structures with parent-child relationships, focusing on binary trees where each node has at most two children.' WHERE id = 'f77408dd-9b45-416d-8cbe-00c1673dfbdd' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Read parent-child relationships and use tree terms to explain hierarchical data.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A company directory has departments, teams, and people. A flat list makes it hard to understand reporting structure.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which relationships form parent and child links? A tree models nested hierarchy without requiring every item to compare with every other item.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A rooted tree has a root, children, leaves, and paths. A binary search tree additionally orders values; ordinary trees do not guarantee fast search unless their shape and rules support it.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Represent a file system folder with child folders and files. Traversal can visit every descendant to calculate total file count.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Draw a three-level category tree. Identify root, one leaf, and the path to a chosen item. What changes if one node has many children?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Use tree language to describe actual relationships, and avoid assuming all trees are balanced or searchable.</p></section>';
-- UPDATE public.lessons SET module_id = 'c9a18717-ccff-4f5d-98a8-6e6c3e2d5936', title = 'Hash Tables and Hashing', content = 'Using hash functions to map keys to indices in an array for efficient lookup.' WHERE id = 'fb4018a7-d998-4221-b85c-ef3256f830d9' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Use a key-based map for lookup and a set for membership while accounting for collisions and ordering.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A support team needs to find a ticket by identifier among thousands of records and avoid processing the same ID twice.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Would scanning every record on every request scale well? A hash function maps keys to locations for expected fast lookup.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A hash map stores key-value associations; a set stores unique values. Collisions require resolution, and performance depends on hash quality, resizing, and implementation. Do not rely on iteration order unless documented.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Map ticket ID `T-42` to its record; use a set of seen IDs to detect duplicates. Validate that IDs are normalized before lookup.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Choose a map or set for a word-frequency counter and for removing duplicate usernames. What should happen when a key already exists?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Hashing makes many lookups efficient in practice, with tradeoffs and assumptions worth stating.</p></section>';
-- UPDATE public.lessons SET module_id = 'c9a18717-ccff-4f5d-98a8-6e6c3e2d5936', title = 'Linked Lists', content = 'Linear collections where elements are not stored contiguously, each pointing to the next.' WHERE id = '233bbc3a-38be-4364-92de-9bc29047185b' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Trace how linked nodes reference neighboring values and compare traversal with indexed access.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A music player frequently inserts a song after the currently playing track, but rarely jumps to a numbered position.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What reference must change to insert a node? Linked structures can make local edits simple while making distant access slower.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A linked list stores nodes connected by references. Traversal visits nodes in sequence; finding position k requires walking from a known end or node. Extra references use memory and bugs can break links.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For `A → C`, insert B by linking A to B and B to C. If only the head is known, reaching the thousandth node takes a sequence of visits.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Draw the pointer updates to remove B from `A → B → C`. What must be handled if B is the head or tail?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Linked lists suit some local update patterns, but they are not automatically faster than arrays.</p></section>';
-- UPDATE public.lessons SET module_id = 'c9a18717-ccff-4f5d-98a8-6e6c3e2d5936', title = 'Stacks and Queues', content = 'Stacks (Last-In, First-Out) and Queues (First-In, First-Out) with their common variations and applications.' WHERE id = '28a3e377-aa71-4cc2-b42e-15553272e160' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Distinguish last-in-first-out and first-in-first-out behavior and select one for a workflow.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>An editor’s Undo should reverse the latest action first, while a printer should normally process submitted jobs in arrival order.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which item leaves first? The order rule determines the right abstraction.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A stack uses push/pop at one end (LIFO). A queue adds at the back and removes from the front (FIFO). Both can be implemented with different underlying structures.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Push “type A,” “delete A,” then “paste B” onto an undo stack. The first undo reverses paste B. A print queue processes job 1 before job 2.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Choose a stack or queue for browser back history, customer support tickets, and a function-call trace. Explain one choice that may need a priority policy.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Order of work is a behavior users notice. Model it directly with the appropriate operations.</p></section>';
-- UPDATE public.lessons SET module_id = 'c9a18717-ccff-4f5d-98a8-6e6c3e2d5936', title = 'Arrays and Strings', content = 'Arrays store elements in contiguous memory locations, enabling efficient indexed access.' WHERE id = '92136dd4-3c4a-44c1-87ed-cb6eb85c640a' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Trace indexed access and insertion in an array-backed collection.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A playlist lets a listener jump directly to track 80, but inserting a song at the beginning shifts many later positions.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Why is jumping to an index different from inserting in the middle? These operations touch different amounts of data.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Arrays store elements in indexed order, enabling constant-time access by index in the usual model. Inserting or deleting within a dense array may require shifting later elements; dynamic arrays occasionally resize.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For `[A, B, C, D]`, insert `X` at index 1: move `B`, `C`, and `D`, then place `X`. Accessing index 3 does not require scanning from index 0.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Trace the array after removing index 0 from `[red, blue, green]`. Which elements move, and which operation is efficient?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A data structure’s name matters less than the cost of its operations in your use case.</p></section>';
-- UPDATE public.courses SET title = 'Web Development Fundamentals', description = 'HTML, CSS, JavaScript, and responsive design. Build your first portfolio website.' WHERE id = 'web_dev' AND description IS NOT DISTINCT FROM 'By the end, you will explain how a browser requests and renders a page, build a semantic responsive site with HTML, CSS, and JavaScript, and check accessibility and delivery. No programming background is required; plan for about 8 hours. Your outcome is a responsive personal or product website.';
-- UPDATE public.modules SET course_id = 'web_dev', title = 'Frontend Development and Deployment', description = 'Building complete websites and deploying them' WHERE id = '55ac6baa-d3b3-40d7-8fb8-038c5febf77d' AND description IS NOT DISTINCT FROM 'Make the site responsive, inspect performance and accessibility, use version control, and prepare a clear deployment handoff.';
-- UPDATE public.modules SET course_id = 'web_dev', title = 'JavaScript Essentials', description = 'Adding interactivity to websites' WHERE id = 'ee5eeab5-5436-46cb-a2c2-153a0994d4a3' AND description IS NOT DISTINCT FROM 'Add small, accessible interactions by connecting JavaScript events to the page structure and state.';
-- UPDATE public.modules SET course_id = 'web_dev', title = 'HTML and CSS Foundations', description = 'Building blocks of web pages' WHERE id = 'e7d1996c-7fa2-4cef-8d49-ebd7ad170e49' AND description IS NOT DISTINCT FROM 'Describe the browser’s role, structure a page with semantic HTML, and style readable layouts with CSS.';
-- UPDATE public.lessons SET module_id = '55ac6baa-d3b3-40d7-8fb8-038c5febf77d', title = 'Deploying Websites', content = 'Shared hosting, VPS, Netlify, Vercel, GitHub Pages, and cloud platforms like AWS and Azure.' WHERE id = '551f6c61-5d6b-435a-934d-8263660b56fd' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Combine semantic markup, responsive styling, a purposeful interaction, and verification into a small portfolio-ready site.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A designer needs a page that helps a visitor understand a product and decide whether to request a demonstration.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What is the visitor trying to learn, and what evidence makes the next action trustworthy? Start with a real user goal, not a collection of effects.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Project plan: choose audience and one task; sketch content hierarchy; build semantic HTML; add responsive CSS; implement one accessible interaction; test keyboard, viewport, and error states; improve one measured issue.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A product site might include a clear problem statement, three benefits tied to evidence, a comparison section, and a labeled contact form. Use placeholder contact data, never real personal data in a public demo.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Prepare a short presentation: audience and problem, design choice, browser flow, accessibility/performance checks, what changed after testing, and one next improvement. Capture evidence only from your own project.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A finished project explains its decisions and limitations. Deployment and persisted learner submissions are separate capabilities; do not claim the platform stores this work.</p></section>';
-- UPDATE public.lessons SET module_id = '55ac6baa-d3b3-40d7-8fb8-038c5febf77d', title = 'Web Accessibility (a11y)', content = 'Following WCAG guidelines to ensure people with disabilities can use websites.' WHERE id = 'bde523c7-cd92-4809-8291-eb65081b9a25' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Check common access barriers in structure, keyboard operation, labels, contrast, and alternative text.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A visitor navigates a product page using only a keyboard and cannot tell which control currently has focus.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Can each task be completed without a mouse, and is the current location visible? Access is part of functionality.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Use semantic HTML, logical focus order, visible focus indicators, sufficient contrast, descriptive labels, and meaningful alternative text. Automated tools catch some issues; human checks remain necessary.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A decorative image can use empty alt text, while a chart needs a concise description and the data in accessible text. A placeholder is not a persistent form label.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Keyboard-test the navigation and form in your project. Record one issue, its impact, and the change that resolves it.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Accessible interfaces give people more than one reliable way to understand and operate the page.</p></section>';
-- UPDATE public.lessons SET module_id = '55ac6baa-d3b3-40d7-8fb8-038c5febf77d', title = 'Web Performance Optimization', content = 'Image optimization, minification, caching, and reducing HTTP requests.' WHERE id = '78733933-1c87-4055-b2e2-b3d639b1fbd4' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Identify common causes of slow page loading and choose a measurement before optimizing.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A portfolio hero uses a 9 MB photo and a custom font. Visitors on mobile data wait several seconds before seeing the page.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which resource delays the first useful view? Measure before replacing assets at random.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Large images, unnecessary JavaScript, render-blocking resources, and layout shifts can hurt performance. Resize and compress images, load only needed code, and preserve dimensions to avoid shifts.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Compare the same page before and after converting an oversized hero to an appropriately sized modern image. Record transfer size and a repeatable load metric.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Inspect your project assets and identify the largest avoidable cost. What metric and device condition will you use to check improvement?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Performance work is a measured tradeoff. Keep visual quality and accessibility while reducing avoidable work.</p></section>';
-- UPDATE public.lessons SET module_id = '55ac6baa-d3b3-40d7-8fb8-038c5febf77d', title = 'Version Control with Git', content = 'Basic Git workflow: cloning, committing, branching, merging, and resolving conflicts.' WHERE id = '0343a06e-b1f9-4c21-8c86-e1f103a17668' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Use a small Git workflow to record intentional changes and recover a known version.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A project owner changes colors, navigation, and JavaScript in one late-night edit, then cannot identify which change broke the page.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>How can each change be reviewed separately? Version control records snapshots and makes comparison possible.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>`git status` shows changed files, `git diff` reveals edits, and a commit records a deliberate set with a message. A branch can isolate a proposed change.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Commit a semantic HTML pass separately from a responsive layout pass. Review the diff and keep secrets and generated files out of the repository.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Plan three small commits for the website project. What belongs in each, and what should never enter version control?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A useful history makes changes reviewable and reversible. Small commits help locate regressions.</p></section>';
-- UPDATE public.lessons SET module_id = '55ac6baa-d3b3-40d7-8fb8-038c5febf77d', title = 'CSS Frameworks: Bootstrap and Tailwind', content = 'Pre-built CSS classes for common UI patterns and responsive layouts.' WHERE id = '252b0808-64d6-4694-ae28-767e4e09d869' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Evaluate a CSS framework as a tool while keeping layout, accessibility, and project requirements in control.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A small team wants to build a consistent set of cards quickly, but its site already has a visual identity and semantic markup.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What problem should the framework solve? Adding a dependency has costs in learning, bundle size, and customization.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Frameworks provide reusable conventions or utility classes. They do not choose good content order, color contrast, or accessible interactions for you.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Before adopting one, prototype a navigation bar and card, compare the output with project styles, and inspect keyboard focus and generated CSS.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>List one benefit and one cost of using a framework for a three-page portfolio. What small experiment would settle the decision?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Choose tools against real constraints, and understand the markup and behavior they generate.</p></section>';
-- UPDATE public.lessons SET module_id = 'ee5eeab5-5436-46cb-a2c2-153a0994d4a3', title = 'Asynchronous JavaScript: Callbacks and Promises', content = 'Techniques for handling asynchronous operations like API requests and file operations.' WHERE id = '5470edb6-5833-4844-b1b0-e4dab704db9b' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain why a network request completes later and handle success and failure without freezing the page.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>The events page requests the schedule from a service. Some visitors have a slow connection or no connection at all.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What should appear while the result is pending? A request has a lifecycle the interface should make visible.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A Promise represents a future result. `async`/`await` makes the flow readable, but requests can reject or return an HTTP error that code must check.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Use `const response = await fetch(url); if (!response.ok) throw new Error(&quot;Schedule unavailable&quot;); const events = await response.json();`. Show loading, empty, and error states.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Sketch how a screen changes through loading, success with zero events, success with events, and failure. Why is an empty result different from an error?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Asynchronous work needs honest loading and recovery states as well as a happy path.</p></section>';
-- UPDATE public.lessons SET module_id = 'ee5eeab5-5436-46cb-a2c2-153a0994d4a3', title = 'Working with Arrays and Objects', content = 'Arrays store ordered collections, while objects store key-value pairs for more complex data structures.' WHERE id = '0c17d8f2-19ef-4b32-9a23-f213e4ee8cee' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Represent a collection of similarly shaped records and select or transform them with array operations.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A volunteer needs to show the next three events from a schedule instead of hardcoding three separate cards.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What fields does every event need? Consistent objects make collection-level operations predictable.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>An array holds an ordered collection; an object groups named properties. Methods such as `filter`, `map`, and `slice` can express selection, display transformation, and limiting.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For `[{title:&quot;Talk&quot;, online:true}, ...]`, filter by `event.online`, map to labels, and limit the displayed list. Handle missing or malformed data explicitly.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Write the sequence of operations to show titles for the first five upcoming events. How would you avoid mutating the original collection?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Model records consistently and choose operations that reveal the intent of the interface.</p></section>';
-- UPDATE public.lessons SET module_id = 'ee5eeab5-5436-46cb-a2c2-153a0994d4a3', title = 'JavaScript Functions and Scope', content = 'Functions are reusable blocks of code that perform specific tasks, with considerations for variable scope and hoisting.' WHERE id = '72716ee2-77c9-4562-9d06-f73b3d82c86c' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Extract repeated behavior into a function with clear inputs and output.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>Two parts of a page format dates differently, so the same event appears as “May 2” in one place and “02/05” in another.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What rule should both views share? A function gives that rule one named home.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A function groups steps and can accept parameters. Local variables stay within their scope, which reduces accidental collisions and makes assumptions explicit.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A `formatEventLabel(title, date)` function can return one display string. Keep formatting separate from DOM updates so it is easier to test.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Design a function that takes a list of events and a category and returns matching events. State its behavior for an empty category.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Small functions are useful when their name, inputs, and result match one clear responsibility.</p></section>';
-- UPDATE public.lessons SET module_id = 'ee5eeab5-5436-46cb-a2c2-153a0994d4a3', title = 'DOM Manipulation and Events', content = 'The Document Object Model (DOM) represents the page so programs can change document structure, style, and content.' WHERE id = '56e16919-8a42-4297-9d8b-0fb9c8c5bd70' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Select a page element, respond to an event, and update text without replacing the whole document.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A visitor filters a list of community events by selecting “online.” They expect the list and result count to update immediately.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What user action starts the change? An event listener connects an action to a small, testable response.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>The DOM is the browser’s object representation of the document. Query a stable element, attach a listener, then update text or classes. Prefer `textContent` for untrusted text.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A button listener can increment a visible counter: `button.addEventListener(&quot;click&quot;, () =&gt; { count += 1; output.textContent = String(count); });` Ensure the button is a real button with a useful label.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Plan the event, state change, and visible result for an “online only” checkbox. How will a keyboard user operate it?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Events turn user actions into behavior. Keep the state change understandable and expose its result.</p></section>';
-- UPDATE public.lessons SET module_id = 'ee5eeab5-5436-46cb-a2c2-153a0994d4a3', title = 'JavaScript Basics', content = 'JavaScript is a lightweight, interpreted programming language with first-class functions.' WHERE id = 'eefe4f3d-833a-42ba-a699-b963e1ce9da2' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Describe how JavaScript values, variables, and expressions can make a page respond to changing information.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>An event page wants to display how many seats remain after a visitor reserves one.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which value changes, and which calculation should use it? Naming state makes the behavior easier to reason about.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>JavaScript stores values in variables, evaluates expressions, and can update the page. Use `const` when a binding is not reassigned and `let` when it is; avoid accidental global state.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>With `const capacity = 40; let reserved = 12; const remaining = capacity - reserved;`, the page can display 28. Validate any user-supplied value before using it.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Trace `let count = 3; count = count + 1;` and write the displayed value. What should the UI say if the input is not a number?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A page interaction is easier to trust when its state and transformations are explicit.</p></section>';
-- UPDATE public.lessons SET module_id = 'e7d1996c-7fa2-4cef-8d49-ebd7ad170e49', title = 'Responsive Design Fundamentals', content = 'Media queries, flexible grids, and flexible images to create layouts that adapt to different screen sizes.' WHERE id = '8e441da8-331b-4ca6-86fe-3e7f6af6de01' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Build a layout that adapts to narrow and wide viewports without horizontal overflow or lost content.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A portfolio looks elegant on a laptop, but the project cards become tiny columns on a phone.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What should reflow, wrap, or remain prioritized? Responsive design preserves the task as space changes.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Start with flexible widths, readable line lengths, and content order. Add media queries when the design no longer fits, not for a list of device models.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A grid such as `repeat(auto-fit, minmax(min(100%, 16rem), 1fr))` lets cards wrap while preserving a useful minimum width. Test text zoom and long labels too.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Plan how a two-column introduction and card grid should behave at 360px and 1100px. Name the first layout constraint that triggers a change.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Responsive means the content remains usable across viewports, input methods, and zoom settings.</p></section>';
-- UPDATE public.lessons SET module_id = 'e7d1996c-7fa2-4cef-8d49-ebd7ad170e49', title = 'CSS Box Model and Positioning', content = 'Margin, border, padding, and content areas, plus static, relative, absolute, fixed, and sticky positioning.' WHERE id = 'b600b184-6665-446c-b4b7-f8a67fcad4e6' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Predict how content, padding, border, and margin contribute to an element’s size and spacing.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A card unexpectedly overflows its column after padding is added, pushing the call-to-action off screen.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Does the declared width include the padding? The box model explains why an element can become wider than its content width.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>The default content box adds padding and border outside the declared width. `box-sizing: border-box` includes them in that width. Positioning should support layout rather than patch every spacing issue.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>With `width: 20rem; padding: 1rem; border: 2px solid`, content-box total width is 22rem plus border; border-box keeps the outside width at 20rem.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Calculate the outside width for a 300px content box with 16px padding and 1px border on each side. Then choose one global rule to simplify sizing.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>When layout surprises you, inspect the box dimensions and containing block before adding offsets.</p></section>';
-- UPDATE public.lessons SET module_id = 'e7d1996c-7fa2-4cef-8d49-ebd7ad170e49', title = 'HTML5 Semantic Elements', content = 'Using elements like header, nav, section, article, aside, and footer to convey meaning about content structure.' WHERE id = 'fccf8ec1-f920-4d60-88fa-c6f685e854a7' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Choose semantic elements for page regions and interactive controls based on their purpose.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A page built entirely from generic containers looks fine, but keyboard users cannot quickly identify its navigation or main content.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What regions should be landmarks? Semantic elements give both browsers and assistive technology useful structure.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>`header`, `nav`, `main`, `article`, `section`, and `footer` communicate roles. Use a `button` for an action and an `a` for navigation; do not rely on clickable generic elements.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>An event card can be an `article` with a heading, details, and a link to the full event. A site-wide menu belongs in `nav` with a clear label when multiple nav regions exist.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Given “open menu,” “go to schedule,” and “event description,” choose the appropriate interactive or structural element for each.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Semantic markup improves navigation and resilience. Pick elements for their meaning and native behavior.</p></section>';
-- UPDATE public.lessons SET module_id = 'e7d1996c-7fa2-4cef-8d49-ebd7ad170e49', title = 'CSS Basics: Styling Web Pages', content = 'Cascading Style Sheets (CSS) is a style sheet language used for describing the presentation of a document written in HTML.' WHERE id = '2e65d8fa-6926-493a-8d20-012be1d65db7' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Connect a CSS rule to selected HTML elements and use readable styles without changing content meaning.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A local club wants the same event page to feel calm and readable on phones and laptops.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which visual choices help a visitor scan the date and action? Styling should strengthen hierarchy rather than compete with it.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A CSS rule has a selector and declarations. Properties such as `color`, `font-size`, and `margin` affect presentation; the cascade resolves rules by origin, specificity, and order.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Use `main { max-width: 42rem; margin: 2rem auto; padding: 1rem; }` to limit line length and center the content. Add contrast and a visible focus style for links.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Style a heading, paragraph, and link. Predict which declaration wins when two rules set the heading color and explain how you checked.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Readable type, spacing, contrast, and focus are functional design decisions, not decoration.</p></section>';
-- UPDATE public.lessons SET module_id = 'e7d1996c-7fa2-4cef-8d49-ebd7ad170e49', title = 'Introduction to HTML', content = 'HyperText Markup Language (HTML) is the standard markup language for documents designed to be displayed in a web browser.' WHERE id = 'ffd9b9bd-2715-4313-b857-2b12c130b37c' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain how HTML gives a page structure and write a small document with meaningful elements.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A community group publishes an event page. Visitors using a screen reader need to find the date and registration details as quickly as sighted visitors.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which text is the page’s main heading and which is a section? Structure communicates relationships to browsers and assistive technology.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>HTML elements describe content roles. A document typically has a doctype, `html`, `head` metadata, and `body` content. Use headings in a logical outline and links for navigation.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A page might contain `&lt;main&gt;&lt;h1&gt;Garden Open Day&lt;/h1&gt;&lt;p&gt;Saturday, 10 am&lt;/p&gt;&lt;a href=&quot;signup.html&quot;&gt;Register&lt;/a&gt;&lt;/main&gt;`. The heading names the page; the link says where it goes.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Sketch the semantic outline for a product page: one title, two sections, and a link to specifications. Avoid choosing tags only for their default appearance.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>HTML is the document’s meaning and structure. CSS can change appearance without changing that meaning.</p></section>';
-- UPDATE public.courses SET title = 'Data Analytics Basics', description = 'Learn to analyze data and create insightful visualizations.' WHERE id = 'data_analytics_basics' AND description IS NOT DISTINCT FROM 'By the end, you will clean a small business dataset, calculate useful summaries, compare performance, and present a recommendation with its limits. No coding experience is required; spreadsheet experience is helpful but optional. Plan for about 6 hours. You will produce a short Business Performance Explorer analysis.';
-- UPDATE public.modules SET course_id = 'data_analytics_basics', title = 'Tools and Technologies', description = 'Software and platforms used in data analytics' WHERE id = 'bf8e5174-25ca-4866-9f8c-171d76b047b3' AND description IS NOT DISTINCT FROM 'Use spreadsheet, SQL, Python, and charting concepts as complementary ways to answer a business question, then communicate a defensible finding.';
-- UPDATE public.modules SET course_id = 'data_analytics_basics', title = 'Data Analysis Techniques', description = 'Methods for analyzing and interpreting data' WHERE id = 'e0c570bf-724b-4e55-a1fe-b23477ad1da3' AND description IS NOT DISTINCT FROM 'Summarize and explore a dataset without confusing a pattern with proof. Practice comparisons, distributions, and responsible interpretation.';
-- UPDATE public.modules SET course_id = 'data_analytics_basics', title = 'Foundations of Data Analytics', description = 'Core concepts and workflow in data analytics' WHERE id = '9c06eca1-bf61-4bc4-9f44-20088d44e78e' AND description IS NOT DISTINCT FROM 'Turn a real question into a trustworthy analysis. Start with the decision, identify suitable data, and check its quality before calculating anything.';
-- UPDATE public.lessons SET module_id = 'bf8e5174-25ca-4866-9f8c-171d76b047b3', title = 'Data Storytelling and Communication', content = 'Tailoring messages to audiences, using narrative techniques, and creating compelling data-driven stories.' WHERE id = '2c6424a5-8af8-4df5-9fe6-4fe593986e9c' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Present a finding, supporting evidence, caveat, and practical recommendation in a concise narrative.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A store owner has two minutes before a planning meeting. A report with twelve charts leaves the team unsure what to do next.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What is the one decision and what evidence changes it? A clear story directs attention while leaving enough detail for scrutiny.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>State the question, finding, evidence, limitation, and recommendation. Separate observed facts from interpretation; show the time period and comparison behind a claim.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Business Performance Explorer project: use a small, synthetic or appropriately authorized sales table. Clean it, compare weekly revenue and units by product, visualize one pattern, and recommend one experiment. Present the source, steps, chart, caveat, and next measure.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Draft a five-sentence presentation: decision question; finding with metric and period; evidence; caveat; proposed action and follow-up measure. Do not imply that a synthetic dataset represents a real business.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A useful analysis ends with a decision someone can test. Preserve the evidence and caveats alongside the recommendation.</p></section>';
-- UPDATE public.lessons SET module_id = 'bf8e5174-25ca-4866-9f8c-171d76b047b3', title = 'Business Intelligence Tools', content = 'Drag-and-drop interfaces for creating interactive dashboards and reports.' WHERE id = 'a48f804c-c500-43e5-bf2a-eac9641a4d57' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Describe how a dashboard helps users monitor a defined set of measures without hiding their definitions.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A regional manager opens a dashboard showing a red sales number but cannot tell whether it is month-to-date, last month, or a target variance.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What decision should the number support? A dashboard is useful only when measures, filters, timing, and ownership are clear.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Business intelligence tools connect data sources to curated measures and interactive views. A dashboard should emphasize a few decision-relevant signals and let a reader inspect context.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A service dashboard might show weekly ticket volume, median first response, and unresolved tickets older than a target. Include the period, unit, filter state, and a link to detail.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Design three measures for a delivery operations dashboard. Define each numerator/denominator or calculation and identify who should act on a change.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A polished dashboard cannot repair an ambiguous metric. Document definitions and make the next action apparent.</p></section>';
-- UPDATE public.lessons SET module_id = 'bf8e5174-25ca-4866-9f8c-171d76b047b3', title = 'Python for Data Analysis', content = 'Building on the Python course to apply programming to data tasks.' WHERE id = '61124e12-d61f-4137-b6d6-c185a993adb1' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Recognize how Python can repeat a transparent cleaning and summary workflow on structured data.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A weekly report is copied by hand every Monday. Small edits to one formula create inconsistent totals across months.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which steps are repeated and checkable? Code can make a process consistent, but it still needs validation and a reader who understands the result.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A common beginner workflow loads a CSV with pandas, inspects columns and missing values, transforms selected fields, and summarizes groups. Confirm library versions and data types before analysis.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Illustrative pandas: `df = pandas.read_csv(&quot;sales.csv&quot;)`; `df[&quot;revenue&quot;] = df[&quot;quantity&quot;] * df[&quot;unit_price&quot;]`; `df.groupby(&quot;product&quot;)[&quot;revenue&quot;].sum()`. Inspect sample rows and totals against a known check.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Write the sequence of checks you would perform before sharing a grouped total. Include one way to detect a wrong data type or missing quantity.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Automation improves repeatability, not truth by itself. Keep the transformation readable and check its output.</p></section>';
-- UPDATE public.lessons SET module_id = 'bf8e5174-25ca-4866-9f8c-171d76b047b3', title = 'Introduction to SQL', content = 'SELECT statements, filtering with WHERE, joins, aggregation, and data modification.' WHERE id = 'be883168-c882-4b55-952d-634bd51c182b' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Read a basic SQL query and use filtering and grouping to answer a clearly defined question.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A shop has thousands of orders and wants weekly units sold by product without copying rows into a new sheet.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which rows belong in the answer, and what should be combined? SQL states those choices explicitly.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A `SELECT` names fields or calculations, `FROM` identifies a table, `WHERE` filters rows, and `GROUP BY` forms groups for aggregates such as `SUM` and `COUNT`.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Example: `SELECT product, SUM(quantity) AS units FROM order_items WHERE order_date &gt;= DATE &#39;2026-01-01&#39; GROUP BY product;` The date filter limits the question; the grouping produces one result per product.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Add a condition for one product category to a grouped query. What changes if you group by both product and month?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A query is an explicit recipe. Check the date boundary, row grain, and grouping before trusting the total.</p></section>';
-- UPDATE public.lessons SET module_id = 'bf8e5174-25ca-4866-9f8c-171d76b047b3', title = 'Working with Spreadsheets', content = 'Formulas, functions, pivot tables, charts, and data analysis toolpak.' WHERE id = '4ef26c24-db5f-4a57-8649-5c78bb374c0e' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Use a tidy table, simple formulas, and filters to inspect a small dataset reproducibly.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A coordinator tracks orders in merged cells, colored notes, and totals typed by hand. A second person cannot reliably update the report.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What makes each row a single observation? Consistent columns let spreadsheet tools calculate and check the data.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Keep one header row, one record per row, one variable per column, and avoid merged cells in the data region. Use formulas for calculations and retain a raw copy.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For a table with date, product, quantity, and unit price, add revenue as `=C2*D2`, filter by date, and compare formula totals with a manual spot check.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Sketch four columns for a small bookshop sales table. Add one formula and one validation rule that would catch an impossible quantity.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A spreadsheet is both a working surface and a data model. Consistent structure makes its results easier to audit.</p></section>';
-- UPDATE public.lessons SET module_id = 'e0c570bf-724b-4e55-a1fe-b23477ad1da3', title = 'Correlation and Regression Analysis', content = 'Measuring how variables change together and predicting one variable based on others.' WHERE id = 'bda33651-195a-47d9-9787-251bf2342e6a' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Interpret a relationship between two measures and explain why correlation alone does not establish cause.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>An ice-cream shop finds that cold-drink sales and sunscreen sales rise together. It considers bundling them as if one product caused the other.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What else changes on hot days? Temperature can influence both sales, creating a shared pattern without either causing the other.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Correlation describes how two variables move together. A simple regression estimates an association in a chosen form and can help make predictions within the observed range; omitted factors and poor data can mislead.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Plot weekly drink sales against temperature, check unusual weeks, and label the result “associated with.” Do not extrapolate far beyond observed temperatures.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Invent a third factor that could explain a relationship between umbrella sales and traffic delays. Write one cautious sentence about the association.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A relationship is a clue. Causal claims need a design that rules out alternative explanations.</p></section>';
-- UPDATE public.lessons SET module_id = 'e0c570bf-724b-4e55-a1fe-b23477ad1da3', title = 'Introduction to Statistical Analysis', content = 'Hypothesis testing, confidence intervals, and understanding statistical significance.' WHERE id = 'b6a43b33-d2f6-4b56-84d8-51c7c3ad430f' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain how sample size, variation, and uncertainty affect a comparison.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A small pilot tests a new checkout flow with eight shoppers. Seven finish quickly, so the team wants to roll it out to everyone.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Would those eight shoppers represent all customers? A sample can vary by chance and by how people were selected.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Statistics offers tools to describe variation and quantify uncertainty. A confidence interval is a range of plausible values under stated assumptions; it is not a guarantee that the result is correct.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Report the number tested, selection method, typical completion time, and range. Compare like-for-like groups and avoid claiming the design caused a difference without an appropriate test.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Name one reason an eight-person convenience sample may differ from all users. What additional evidence would you collect before a broad rollout?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Use uncertainty to calibrate confidence and the size of the decision, not to decorate a weak result with technical language.</p></section>';
-- UPDATE public.lessons SET module_id = 'e0c570bf-724b-4e55-a1fe-b23477ad1da3', title = 'Exploratory Data Analysis (EDA)', content = 'Using summary statistics and visualizations to understand data distribution, relationships, and outliers.' WHERE id = '883f1a65-fa15-4cc3-97ad-fb32c61a1e4f' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explore a dataset with counts, distributions, and segmented comparisons before settling on a conclusion.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A shop sees total revenue rise and assumes every product is selling better. A deeper view shows the increase came from one seasonal item.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What changes when you split revenue by product and week? A total can hide variation between groups.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Exploratory analysis checks shape, missingness, unusual values, and relationships. Try a few relevant slices, record what you looked for, and distinguish a lead from a tested explanation.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Compare orders and revenue by product and week; then inspect whether a promotion or stock shortage overlaps the change.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Pick one metric and two meaningful groups. State what comparison you would inspect first and one pattern that would change your next question.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Exploration helps form hypotheses. It does not turn a surprising chart into causal evidence.</p></section>';
-- UPDATE public.lessons SET module_id = 'e0c570bf-724b-4e55-a1fe-b23477ad1da3', title = 'Data Visualization Principles', content = 'Choosing the right chart type, avoiding misleading representations, and following visualization best practices.' WHERE id = 'bd02bd3c-3732-4013-9f1c-2a02341a027f' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Match a chart to the comparison, time trend, distribution, or relationship a reader needs to see.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A product team puts 18 categories in a pie chart. Readers cannot compare the similarly sized slices or find the biggest change.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What comparison should be easiest? A chart should reduce effort for that task instead of decorating the report.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Use bars for category comparisons, lines for ordered time, and histograms for numeric distributions. Label units, state the period, keep scales honest, and provide a text summary for access.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>To compare monthly returns across four product lines, use a grouped bar chart or small multiples. Start a bar axis at zero when bar length encodes magnitude.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Choose a chart for daily website visits and another for the distribution of delivery times. Add the exact title and unit each reader needs.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A truthful chart makes its question, scale, and units easy to inspect.</p></section>';
-- UPDATE public.lessons SET module_id = 'e0c570bf-724b-4e55-a1fe-b23477ad1da3', title = 'Descriptive Statistics', content = 'Measures of central tendency (mean, median, mode) and dispersion (range, variance, standard deviation).' WHERE id = '74aa47fc-5416-4a25-b362-bc19133a9676' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Calculate counts, mean, median, and range, then select a summary that represents the question.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A delivery team reports an average arrival time of 31 minutes. Most deliveries take about 24 minutes, but one storm delay took 115 minutes.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Does the average describe a typical delivery? A single extreme value can pull the mean away from most observations.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Mean adds values and divides by count; median is the middle ordered value; range is maximum minus minimum. Counts describe frequency. None explains why values differ.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For 18, 20, 22, 24, 71 minutes, mean is 31 and median is 22. Show both when the unusually long delivery matters.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>For values 4, 5, 5, 6, 30, calculate mean and median. Which better describes an ordinary day, and what important event would it hide?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A statistic is a summary with assumptions. Pair it with context and, when useful, a view of the distribution.</p></section>';
-- UPDATE public.lessons SET module_id = '9c06eca1-bf61-4bc4-9f44-20088d44e78e', title = 'Data Quality and Cleaning Basics', content = 'Handling missing values, removing duplicates, correcting inconsistencies, and standardizing formats.' WHERE id = 'ed8b0f82-e159-4f45-bb89-dc1700b4eebf' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Detect missing, duplicated, inconsistent, and implausible values and document any correction.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A sales report shows two orders with the same receipt number and a blank quantity. Deleting both rows would remove genuine information as well as the duplicate.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which row is repeated, and what evidence identifies it? Cleaning should repair a known issue while keeping a trace of the original.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Check uniqueness, required fields, allowed ranges, consistent units, and date formats. Missing values are not automatically zero; decide whether to exclude, investigate, or label them.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>If one item price is recorded as 1200 while similar prices are near 12, verify the source and currency before correcting. Write down the rule and count affected rows.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Review a tiny table with a repeated order ID, blank quantity, and mixed date formats. Mark each issue and propose a reversible treatment.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A clean dataset is one whose known limitations and transformations are understood, not one with every blank erased.</p></section>';
-- UPDATE public.lessons SET module_id = '9c06eca1-bf61-4bc4-9f44-20088d44e78e', title = 'Data Sources and Collection Methods', content = 'Internal databases, external APIs, surveys, sensors, web scraping, and manual entry.' WHERE id = '63dea197-9485-4a54-982d-b05e2521f2d1' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Identify who created a dataset, how it was collected, and what population or time period it represents.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A manager compares a voluntary customer survey with every recorded transaction and wonders why the survey reports more complaints.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Who chose to answer the survey? Voluntary responses can overrepresent people with strong opinions, while transactions answer different questions entirely.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A source has provenance: its origin, collection method, definitions, and coverage. A sample is the part observed. If coverage misses a group or period, results may not represent the full population.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Before comparing survey answers with sales, record the dates, invite method, response count, and transaction definition. Avoid joining records unless there is a legitimate, privacy-safe key.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>For a question about weekend wait times, list a direct source, a likely coverage gap, and one consent or privacy consideration.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>More rows do not guarantee representative evidence. Explain how the data came to exist.</p></section>';
-- UPDATE public.lessons SET module_id = '9c06eca1-bf61-4bc4-9f44-20088d44e78e', title = 'Types of Data: Quantitative vs Qualitative', content = 'Quantitative data is numerical and measurable, while qualitative data is descriptive and conceptual.' WHERE id = 'f92de177-8e00-42c3-afe0-b4b1c6abba3a' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Distinguish numeric measurements from categories and text, and choose a suitable summary for each.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A café asks customers for a star rating and an optional comment. The owner wants to know both how ratings changed and what customers found frustrating.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Can a comment be averaged? Ratings are numeric, while comments carry meaning in words. Treating them as the same kind of data hides useful detail.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Quantitative data can be counted or measured, such as minutes waited or items sold. Qualitative data describes groups or experiences, such as order channel or a written complaint. A number used as a label, like postal code, is still categorical.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Summarize wait time with a median and range; count ratings by star; group comments into transparent themes and preserve representative examples.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Classify “5 stars,” “5 minutes,” “online order,” and “customer said the menu was unclear.” Which can be averaged? Which needs grouping or interpretation?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Choose a method based on what a field means, not how it looks in a cell.</p></section>';
-- UPDATE public.lessons SET module_id = '9c06eca1-bf61-4bc4-9f44-20088d44e78e', title = 'The Data Analytics Workflow', content = 'Asking questions, data collection, data cleaning, analysis, interpretation, and communicating results.' WHERE id = '7925e538-e9d6-4b94-8901-b6732713ea61' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Arrange an analysis into question, data, preparation, exploration, communication, and action.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A team receives a spreadsheet and immediately calculates a monthly average. Later they discover several rows are duplicated and the date range excludes the busiest week.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What check would have prevented the wrong conclusion? A repeatable workflow puts the question and data checks before the calculation.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Define the decision; inspect source and time range; clean with a record of changes; summarize; visualize; explain uncertainty; recommend a next step. Return to the question when results do not answer it.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For a delivery service, ask “Which routes missed the promised window last week?” Confirm what counts as late, inspect missing timestamps, then calculate the late share by route.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Put these tasks in order for a question you care about: choose a chart, define the question, check missing values, recommend an action. Explain why your order protects trust.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A workflow is a set of quality gates, not paperwork. Correct interpretation depends on the decisions made at every step.</p></section>';
-- UPDATE public.lessons SET module_id = '9c06eca1-bf61-4bc4-9f44-20088d44e78e', title = 'What is Data Analytics?', content = 'Data analytics involves examining datasets to draw conclusions about the information they contain, increasingly with specialized systems and software.' WHERE id = '9abc33d1-c163-4e2a-a690-e8b2ed30d00a' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain how analysis connects a decision to evidence and a useful next step.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A neighborhood shop has fewer repeat visits this month. The owner needs to decide whether to change opening hours, promote a product, or first collect better information.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which decision is actually being made? A useful analysis starts by keeping that decision in view.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Data analytics is the process of asking a focused question, preparing relevant evidence, examining it, and explaining what it can support.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For example, compare weekly repeat-customer counts with opening hours and promotion dates. A lower count is a signal to investigate, not proof that one change caused it.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Write one question the shop could answer this week. Name the decision it would inform and one alternative explanation for the result.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Analysis earns its place when evidence helps someone make a better decision. Keep the question and the limits of the evidence visible.</p></section>';
-- COMMIT;
